// CALLEE: beacon-chain/state/stateutil/trie_helpers.go:MerkleizeTrieLeaves (lines 283-301)
func MerkleizeTrieLeaves(layers [][][32]byte, hashLayer [][32]byte) ([][][32]byte, [][32]byte, error) {
	i := 1
	chunkBuffer := bytes.NewBuffer([]byte{})
	chunkBuffer.Grow(64)
	for len(hashLayer) > 1 && i < len(layers) {
		if !math.IsPowerOf2(uint64(len(hashLayer))) {
			return nil, nil, errors.Errorf("hash layer is a non power of 2: %d", len(hashLayer))
		}
		hashLayer = htr.VectorizedSha256(hashLayer)
		layers[i] = hashLayer
		i++
	}
	return layers, hashLayer, nil
}

// PRIMARY: beacon-chain/state/stateutil/trie_helpers.go:recomputeRootFromLayer (lines 141-186)
func recomputeRootFromLayer(idx int, layers [][]*[32]byte, chunks []*[32]byte,
	hasher func([]byte) [32]byte) ([32]byte, [][]*[32]byte, error) {
	root := *chunks[idx]
	layers[0] = chunks
	// The merkle tree structure looks as follows:
	// [[r1, r2, r3, r4], [parent1, parent2], [root]]
	// Using information about the index which changed, idx, we recompute
	// only its branch up the tree.
	currentIndex := idx
	var combinedChunks [64]byte
	for i := 0; i < len(layers)-1; i++ {
		isLeft := currentIndex%2 == 0
		neighborIdx := currentIndex ^ 1

		var neighbor [32]byte
		if layers[i] != nil && len(layers[i]) != 0 && neighborIdx < len(layers[i]) {
			neighbor = *layers[i][neighborIdx]
		}
		if isLeft {
			copy(combinedChunks[:32], root[:])
			copy(combinedChunks[32:], neighbor[:])
		} else {
			copy(combinedChunks[:32], neighbor[:])
			copy(combinedChunks[32:], root[:])
		}
		parentHash := hasher(combinedChunks[:])
		root = parentHash
		parentIdx := currentIndex / 2
		rootVal := root
		if len(layers[i+1]) == 0 {
			layers[i+1] = append(layers[i+1], &rootVal)
		} else {
			layers[i+1][parentIdx] = &rootVal
		}
		currentIndex = parentIdx
	}
	if len(layers[0]) == 1 {
		return *layers[0][0], layers, nil
	}
	return root, layers, nil
}

// RELATED: beacon-chain/state/stateutil/trie_helpers.go:ReturnTrieLayerVariable (lines 46-80)
func ReturnTrieLayerVariable(elements [][32]byte, length uint64) [][]*[32]byte {
	depth := ssz.Depth(length)
	layers := make([][]*[32]byte, depth+1)
	if len(elements) == 0 {
		zerohash := trie.ZeroHashes[depth]
		layers[len(layers)-1] = []*[32]byte{&zerohash}
		return layers
	}
	// ... builds layers bottom-up via VectorizedSha256
	for i := uint8(0); i < depth; i++ {
		layerLen := len(layers[i])
		oddNodeLength := layerLen%2 == 1
		if oddNodeLength {
			zerohash := trie.ZeroHashes[i]
			elements = append(elements, zerohash)
			layerLen++
		}
		layers[i+1] = make([]*[32]byte, layerLen/2)
		elements = htr.VectorizedSha256(elements)
		for j := range elements {
			layers[i+1][j] = &elements[j]
		}
	}
	return layers
}

// PRIMARY: beacon-chain/state/stateutil/validator_root.go:ValidatorFieldRoots (lines 25-60)
func ValidatorFieldRoots(validator *ethpb.Validator) ([][32]byte, error) {
	var fieldRoots [][32]byte
	if validator != nil {
		pubkey := bytesutil.ToBytes48(validator.PublicKey)
		withdrawCreds := bytesutil.ToBytes32(validator.WithdrawalCredentials)
		var effectiveBalanceBuf [32]byte
		binary.LittleEndian.PutUint64(effectiveBalanceBuf[:8], validator.EffectiveBalance)
		// Slashed.
		var slashBuf [32]byte
		if validator.Slashed {
			slashBuf[0] = uint8(1)
		} else {
			slashBuf[0] = uint8(0)
		}
		var activationEligibilityBuf [32]byte
		binary.LittleEndian.PutUint64(activationEligibilityBuf[:8], uint64(validator.ActivationEligibilityEpoch))
		var activationBuf [32]byte
		binary.LittleEndian.PutUint64(activationBuf[:8], uint64(validator.ActivationEpoch))
		var exitBuf [32]byte
		binary.LittleEndian.PutUint64(exitBuf[:8], uint64(validator.ExitEpoch))
		var withdrawalBuf [32]byte
		binary.LittleEndian.PutUint64(withdrawalBuf[:8], uint64(validator.WithdrawableEpoch))
		// Public key.
		pubKeyRoot, err := merkleizePubkey(pubkey[:])
		if err != nil {
			return [][32]byte{}, err
		}
		fieldRoots = [][32]byte{pubKeyRoot, withdrawCreds, effectiveBalanceBuf, slashBuf,
			activationEligibilityBuf, activationBuf, exitBuf, withdrawalBuf}
	}
	return fieldRoots, nil
}

// CALLER: beacon-chain/state/stateutil/validator_root.go:ValidatorRootWithHasher (lines 14-21)
func ValidatorRootWithHasher(validator *ethpb.Validator) ([32]byte, error) {
	fieldRoots, err := ValidatorFieldRoots(validator)
	if err != nil {
		return [32]byte{}, err
	}
	return ssz.BitwiseMerkleize(fieldRoots, uint64(len(fieldRoots)), uint64(len(fieldRoots)))
}
